 'el15': lambda d: d['el']+15,
 'lelw0': lambda d: d['lel']*d['w0']/100,
 'lelwkg': lambda d: d['lel']*d['w0kg'],
 'lelbmi': lambda d: d['lel']*d['bmi'],
}
DER_SRC = {'el15':"d['el']+15",'lelw0':"d['lel']*d['w0']/100",'lelwkg':"d['lel']*d['w0kg']",'lelbmi':"d['lel']*d['bmi']"}
for k,f in DER.items(): D[k]=f(D)
fs = sys.argv[1].split(','); lam=float(sys.argv[2]); shrink=float(sys.argv[3]) if len(sys.argv)>3 else 0.0
X=np.column_stack([D[f] for f in fs])
def fit(Xt,yt):
    mu=Xt.mean(0); sd=Xt.std(0)+1e-9; Z=(Xt-mu)/sd; ym=yt.mean()
    b=np.linalg.solve(Z.T@Z+lam*np.eye(Z.shape[1]),Z.T@(yt-ym))
    coef=b/sd; icpt=ym-(mu*coef).sum()
    return coef,icpt
# LOPO residuals on scored
res=[];pm={}
for p in sorted(set(P)):
    tr=P!=p; te=(P==p)&S
    if te.sum()==0: continue
    c,i=fit(X[tr],Y[tr]); r=Y[te]-(X[te]@c+i); res.extend(r); pm[p]=np.abs(r).mean()
