        if te.sum()==0: continue
        pa=preds(['lel'],3,tr,te,lad); pb=preds(fsB,3,tr,te,lad)
        errs[p]=np.abs((1-alpha)*pa+alpha*pb-Y[te]).mean()
    return np.mean(list(errs.values()))
for lad in [False,True]:
    for a in [0,0.25,0.5,0.75,1.0]:
        print('lad' if lad else 'ls', a, '%.4f %.4f'%(ev(a,S,lad),ev(a,E4,lad)))
