import pickle, numpy as np, sys
keys,M,Y,P,S = pickle.load(open('ds.pkl','rb'))
D={k:M[:,i] for i,k in enumerate(keys)}
D['lelwkg']=D['lel']*D['w0kg']
E4=D['el']>=4
alpha=float(sys.argv[1]); lam=3.0; infl=float(sys.argv[2]) if len(sys.argv)>2 else 1.0
FA=['lel']; FB=['lel','w0kg','lelwkg','bmi']; FU=FB
def lad(fs,tr,iters=80):
    X=np.column_stack([D[f] for f in fs])[tr]; y=Y[tr]
    mu=X.mean(0); sd=X.std(0)+1e-9; Z=np.column_stack([np.ones(len(y)),(X-mu)/sd])
    w=np.ones(len(y)); R=lam*np.eye(Z.shape[1]); R[0,0]=0
    for _ in range(iters):
        b=np.linalg.solve(Z.T@(Z*w[:,None])+R,Z.T@(w*y)); w=1/np.maximum(np.abs(y-Z@b),0.02)
    coef=b[1:]/sd; icpt=b[0]-(mu*coef).sum()
    full=np.zeros(len(FU)); 
    for f,c in zip(fs,coef): full[FU.index(f)]=c
    return full,icpt
def blend(tr):
    ca,ia=lad(FA,tr); cb,ib=lad(FB,tr); return (1-alpha)*ca+alpha*cb,(1-alpha)*ia+alpha*ib
XU=np.column_stack([D[f] for f in FU])
rS=[];rE=[];pmS={};pmE={}
for p in sorted(set(P)):
    c,i=blend(P!=p); pr=XU@c+i
    te=(P==p)&E4; r=Y[te]-pr[te]; rE.extend(r); pmE[p]=np.abs(r).mean()
    te=(P==p)&S
    if te.sum(): r=Y[te]-pr[te]; rS.extend(r); pmS[p]=np.abs(r).mean()
rS=np.array(rS); rE=np.array(rE)
print('alpha',alpha,'LOPO pbMAE scored %.4f E4 %.4f'%(np.mean(list(pmS.values())),np.mean(list(pmE.values()))))
for nm,r in [('S',rS),('E4',rE)]: print(nm,'q05 %.3f q95 %.3f'%(np.quantile(r,.05),np.quantile(r,.95)))
lo=float(np.quantile(rE,.05))*infl; hi=float(np.quantile(rE,.95))*infl
def isc(r,lo,hi): return np.mean((hi-lo)+20*np.maximum(0,lo-r)+20*np.maximum(0,r-hi))
print('interval score LOPO S %.3f E4 %.3f cov S %.3f'%(isc(rS,lo,hi),isc(rE,lo,hi),np.mean((rS>=lo)&(rS<=hi))))
coef,icpt=blend(np.ones(len(Y),bool))
print('coef',dict(zip(FU,np.round(coef,4))),'icpt %.4f lo %.3f hi %.3f'%(icpt,lo,hi))
feat_src=open('feats.py').read()
src=f'''"""Variant 3A: forecast core temperature 15 min ahead from causal history only (core temp is never an input).
Frozen linear model = {1-alpha:.2f} x LAD[log(elapsed+15)] + {alpha:.2f} x LAD[log(elapsed+15), W0/kg, log(elapsed+15)*W0/kg, BMI],
fitted on all train.json origins (ridge-penalised IRLS median regression). Elapsed time is relative to the first
history row, so absolute clock shifts do not matter. Interval = mean + LOPO residual 5%/95% quantiles."""
{feat_src}
FEATS = {FU!r}
COEF = {[float(c) for c in coef]!r}
ICPT = {float(icpt)!r}
LO = {lo!r}
HI = {hi!r}
def predict(request):
    h = [r for r in (request.get('history') or []) if isinstance(r, dict) and r.get('time_min') is not None]
    if not h:
        m = 38.3
        return {{'mean': m, 'lower': m + LO, 'upper': m + HI}}
    d = features(h)
    d['lelwkg'] = d['lel'] * d['w0kg']
    m = ICPT + sum(c * d[f] for c, f in zip(COEF, FEATS))
    m = max(36.0, min(40.5, m))
    return {{'mean': float(m), 'lower': float(m + LO), 'upper': float(m + HI)}}
'''
open('submission.py','w').write(src)
